import{_ as o,o as e,c as d,a2 as r}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"15. 已知限制与常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),a={name:"faq.md"};function n(c,t,s,p,g,i){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="_15-已知限制与常见问题" tabindex="-1">15. 已知限制与常见问题 <a class="header-anchor" href="#_15-已知限制与常见问题" aria-label="Permalink to &quot;15. 已知限制与常见问题&quot;">​</a></h1><h2 id="_15-1-当前不可用的功能" tabindex="-1">15.1 当前不可用的功能 <a class="header-anchor" href="#_15-1-当前不可用的功能" aria-label="Permalink to &quot;15.1 当前不可用的功能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>状态</th></tr></thead><tbody><tr><td><code>/rtp</code> 随机传送</td><td>命令被禁用，权限也拒绝</td></tr><tr><td>新手礼包 / <code>/kit</code></td><td>礼包目录为空，当前没有可领礼包</td></tr><tr><td>系统商店 / 拍卖行</td><td>未安装</td></tr><tr><td>领地出租 / 领地拍卖</td><td>配置关闭</td></tr><tr><td>联盟升级 / 联盟经验</td><td>没有经验来源，所有联盟固定 Lv.1</td></tr><tr><td>领地维护税</td><td>关闭，不扣每日税</td></tr><tr><td>公共传送点</td><td>目前仅有主城 <code>court</code></td></tr></tbody></table><h2 id="_15-2-常见问题" tabindex="-1">15.2 常见问题 <a class="header-anchor" href="#_15-2-常见问题" aria-label="Permalink to &quot;15.2 常见问题&quot;">​</a></h2><p><strong>Q：为什么我有 8 钻石余额，背包里却没有钻石？</strong> A：8 是初始记账余额。用 <code>/bank takeout 8</code> 取出钻石，或直接用它买东西/转账。</p><p><strong>Q：为什么我挖了钻石，余额没变？</strong> A：挖到的钻石是物品，不是余额。需要 <code>/bank add &lt;数量&gt;</code> 存入。</p><p><strong>Q：为什么我不能在自家领地破坏方块？</strong> A：确认你是领地屋主，且没有把自己分配到一个没有 <code>build</code> 权限的组。用 <code>/pclaim info</code> 和 <code>/pclaim explain &lt;领地&gt; build</code> 检查。</p><p><strong>Q：为什么别人能走进我的领地？</strong> A：默认 <code>move=true</code>，领地不是封闭盒子；外人只是不能破坏/开箱子/用按钮。想完全禁止进入，把 <code>move</code> 设为 <code>off</code>。</p><p><strong>Q：为什么我不能开自家箱子？</strong> A：先用 <code>/pclaim explain &lt;领地&gt; container</code> 看是哪条规则拒绝；屋主一般不受成员组限制，若仍被拒绝，检查是否有 WorldGuard 等其他保护重叠。</p><p><strong>Q：为什么领地内不能 PvP？</strong> A：领地默认 <code>pvp=off</code>。屋主可开启；有外人在场时不能改，需要先让对方离开。</p><p><strong>Q：为什么我只能有一块家园领地？</strong> A：当前每人限 1 块。联盟领地是另一套系统，需要加入联盟后使用 <code>/gclaim</code>。</p><p><strong>Q：为什么第 9 个家要收费？</strong> A：前 8 个家免费，第 9 个起每个 8 钻石；公开家每个 16 钻石。</p><p><strong>Q：为什么 <code>/home</code> 和 <code>/pclaim home</code> 不一样？</strong> A：<code>/home</code> 是 HuskHomes 的个人家园；<code>/pclaim home</code> 是传送到你的领地。两者独立。</p><p><strong>Q：为什么我的联盟一直是 Lv.1？</strong> A：当前版本没有联盟经验来源，所有联盟固定 Lv.1；人数上限 10、免费领地额度 1,024。扩容只能买额度。</p><p><strong>Q：联盟领地扩容为什么这么贵？</strong> A：按当前配置实际 100 钻石/格（注释写 1/格，相差 100 倍），从联盟金库扣；购买前看确认界面的实际扣费。建议先用免费 1,024 格，确有必要再买。</p><p><strong>Q：为什么我不能创建联盟领地？</strong> A：需要盟主或拥有 <code>union.claim.create</code> 权限的职位；普通成员只能建造和使用。用 <code>/union rank</code> 检查职位权限。</p><p><strong>Q：死亡会掉东西吗？</strong> A：服务器文件未启用 keepInventory，默认死亡会掉落物品与经验；若管理组临时开启，以游戏内提示为准。贵重物品请存箱、放领地或末影箱。</p><p><strong>Q：主世界有多大？</strong> A：服务器未在配置中固定世界边界，具体以游戏内 <code>/worldborder get</code> 为准。</p><p><strong>Q：基岩版名字为什么带 <code>BE-</code>？</strong> A：Floodgate 的前缀，用于区分基岩版玩家；不影响游戏功能。</p><p><strong>Q：Java 版可以用离线账号吗？</strong> A：不能。代理开启正版验证，必须使用正版账号。</p><p><strong>Q：服务器有商店吗？</strong> A：没有系统商店。钻石通过挖矿、探索和玩家交易获得；大额交易请自行约定，注意防骗。</p><p><strong>Q：发现 bug 或被骗怎么办？</strong> A：保留截图/录屏、时间、地点和玩家名，联系在线管理员。不要自行利用漏洞。</p>',22)])])}const _=o(a,[["render",n]]);export{h as __pageData,_ as default};
